import { assert, assertEquals, assertNotEquals } from 'jsr:@std/assert@1';
import { entryFingerprint } from './entryFingerprint.ts';

// Mirrors src/lib/entryFingerprint.test.js over the same fixture, which was
// generated by server/deskBrief.mjs, so the three copies cannot drift.
interface Case {
  note: string;
  tier: string;
  feature: string;
  row: Record<string, unknown>;
  sha: string;
}

const fixture = JSON.parse(
  await Deno.readTextFile(new URL('../../../src/lib/__fixtures__/entryFingerprint.json', import.meta.url)),
) as Case[];

Deno.test('reproduces every fixture fingerprint', async () => {
  assert(fixture.length >= 8);
  for (const c of fixture) assertEquals(await entryFingerprint(c.row, c.feature, c.tier), c.sha, c.note);
});

Deno.test('a changed field changes the fingerprint; an internal key does not', async () => {
  const row = { title: 'Port', status: 'Open' };
  const a = await entryFingerprint(row, 'Infra', 'global');
  assertNotEquals(await entryFingerprint({ ...row, status: 'Closed' }, 'Infra', 'global'), a);
  assertEquals(await entryFingerprint({ ...row, __rowIndex: 4 }, 'Infra', 'global'), a);
});
